74	        return registryImpl;
75	    }
76	#endif
77	
78	    std::shared_ptr<TilingCases> RegisterOp(const std::string& op_type, const int32_t soc_version)
79	    {
80	        auto soc_iter = registry_map_.find(soc_version);
